/**
 * Which DEPLOYMENT a build is for, as a second seed rather than a second stylesheet.
 *
 * THE FAILURE THIS PREVENTS IS ONE KEYSTROKE WIDE: a person with two windows open, one on the
 * alpha record and one on the real one, deleting a row from the wrong one. Nothing in the product
 * currently distinguishes them, and the two screens are byte-identical.
 *
 * SO IT IS A SEED AND NOT A CSS OVERRIDE, and that is the whole argument of this package. 28 §1
 * says a theme is "a token document and nothing else"; 28 §3 says the palette is GENERATED by
 * contrast so that "the checks the generator drives become tautologies"; 28 §4.4 lists the sixteen
 * checks a palette must clear. A hand-written `--accent: orange` in a stylesheet is outside all of
 * it: no ink ramp is re-solved against it, no `accent-ink` is proved to clear 4.5:1 on it, no
 * `accent-edge` is proved to hold 3:1, and check K — a link must differ from body ink and from an
 * overdue figure in LIGHTNESS — is never asked. An environment that is harder to read than the
 * product is not a safety feature.
 *
 * AND THE HUE IS NOT A TASTE CALL, because this package already contains the function whose entire
 * job is the question being asked. `nextAccentHue(existing)` returns the point on the circle
 * farthest from every hue already spent — measured AFTER dichromat simulation rather than on the
 * circle, and never within `HUE_FLOOR` degrees of an intent anchor (28 §3.2). Asked for a second
 * mark to stand beside the brand, it answers 286. That is the answer, and it did not need a
 * designer.
 *
 * WHAT MOVES AND WHAT DOES NOT. Only the accent roles change: `accent`, `accent-edge`,
 * `accent-hover`, `accent-press`, `accent-text`, `accent-ink`, the two mark constants that
 * follow the hue, and since 2026-10-07 the working accent (`action` and its five), which the house
 * pins only beside its own red (`Seed.action`), so an environment's buttons and links wear its hue
 * too. The five surfaces, the board and the tile, the four inks, both boundaries, all four intents and all four
 * `-fill` variants are byte-identical to the house palette, because the intents are solved at fixed
 * hue anchors against a ground whose chroma is capped well below any seed's. Measured: every
 * non-accent role identical in both schemes. Three consequences, all wanted —
 *
 *   1. A alpha screenshot and a production screenshot differ in exactly the places the accent is
 *      painted, so they can still be compared. A second ground would make every visual diff useless.
 *   2. `danger` stays red in alpha. Red goes on meaning "this is owed, this is late, this is
 *      wrong" and stops meaning "this is BrainDog", which is the correct division of the one hue
 *      the product cares most about.
 *   3. The environment cannot introduce a contrast regression that the house theme does not already
 *      have, because everything a contrast floor is measured against is the same object.
 */

import { gamutMap } from './color.ts';
import {
  BRAND_RED,
  HOUSE_PROFILE,
  build,
  hueGap,
  nextAccentHue,
  normalise,
  INTENT_HUE,
  type Built,
  type Profile,
  type Seed,
} from './build.ts';

/**
 * The deployments that get their own palette. `''` — production — is not a member: it is the
 * absence of one, and the house theme is what it gets.
 *
 * A CLOSED LIST OF ONE, and it stays closed. 30 §2's argument for every closed list in this corpus
 * applies here with no change: "a list enforced only by a validator is a list one code path
 * forgets". A third deployment costs a second generated stylesheet and a second run of the sixteen
 * checks, and both of those are gated — so adding one is a diff a reviewer sees.
 */
export const ENVIRONMENTS = ['alpha'] as const;
export type Environment = (typeof ENVIRONMENTS)[number];

/**
 * The hue an environment's accent sits on: the farthest legal point from the brand's own.
 *
 * DETERMINISTIC AND COMPUTED, NOT PINNED. A pinned literal is a value that stops being derived the
 * moment somebody improves the scorer, and then the derivation in this comment is a story about a
 * number rather than a description of one. It is computed, and `environment.test.ts` asserts the
 * answer is 286 — so a change to `nextAccentHue` is a red test naming the degree it moved to,
 * followed by a red `theme` gate naming the stylesheet that no longer matches its generator. Loud,
 * twice, in the right order.
 *
 * WHY `nextAccentHue` AND NOT A NEW SEARCH. Its scoring is exactly the question: it walks the
 * circle, refuses every hue within 20 degrees of `earn`, `warn`, `danger` or `info`, paints the two
 * mark swatches at the profile's own (L, C) constants, and maximises the smallest delta-E to the
 * existing marks under all three deficiencies. "The second mark, beside the brand" is what an
 * environment accent IS.
 */
/* Away from the house accent AND from the mark, now that they are two colours, and only among the
   hues that hold the accent's own lightness and chroma inside sRGB. The scorer measures marks,
   which are low-chroma and fit anywhere; the fill is not, and the first answer without this filter
   was a cyan that the gamut clipped to half its chroma, 3.9 apart from the indigo to a tritanope. */
export const environmentHue = (house: Seed): number => {
  const c = normalise(house.accent);
  return nextAccentHue([c.H, normalise(BRAND_RED).H], HOUSE_PROFILE, (h) => Math.abs(gamutMap({ L: c.L, C: c.C, H: h }).C - c.C) <= 0.005);
};

/**
 * The house seed with one number changed.
 *
 * THE LIGHTNESS AND THE CHROMA ARE THE BRAND'S, deliberately. The house seed's own note works
 * through the window those two live in — "a white label on the fill needs 4.5:1, which caps the
 * colour's luminance, while the fill against the lightest surface and against the darkest each need
 * 3:1 under 1.4.11, and those pull opposite ways. The window is Y in [0.151, 0.183]" — and that
 * window is a property of the ladder, not of the hue. Rotating inside it inherits the whole
 * argument; picking a new (L, C) would mean re-deriving it, and getting it wrong is a primary
 * button that fails AA at the moment somebody presses it.
 *
 * AND THE NEUTRALS STAY OLIVE. `record.ts` already records what happens when a saturated seed takes
 * the surfaces with it: "at L 0.16 even a whisper of chroma at a warm hue reads as dirt". The
 * environment changes the accent, the marks and the links, which is where colour means anything.
 */
export function environmentSeed(house: Seed): Seed {
  const c = normalise(house.accent);
  /* Emitted as `oklch(L C H)` rather than as a hex, because that is the form the dialect's own
     grammar prefers for a derived colour and it keeps the derivation legible in the seed. The
     generator gamut-maps and quantises it on the way in, so the value that ships is sRGB either
     way. */
  return { ...house, accent: `oklch(${c.L.toFixed(3)} ${c.C.toFixed(3)} ${environmentHue(house)})` };
}

/**
 * The palette an environment ships, at either profile.
 *
 * ONE SEED, TWO PROFILES, exactly as 28 §3.1 has it for high contrast: "there is no high-contrast
 * dialect and no second seed". The hue is always derived against `HOUSE_PROFILE`'s mark constants,
 * because the marks a reader compares are the ones the ordinary theme paints — deriving a second
 * hue from the high-contrast profile would give one deployment two identities.
 */
export const environmentTheme = (house: Seed, profile: Profile, id: string): Built =>
  build(environmentSeed(house), profile, id);

/**
 * How far an environment accent is from every intent anchor, for the report a reviewer reads.
 *
 * EXPORTED BECAUSE THE NUMBER IS THE ARGUMENT. The generator's separability search covers intent
 * against intent and deliberately excludes the accent — "an accent is chrome; it never appears as a
 * row's verdict" — so nothing in `checks.ts` will ever refuse an accent for sitting on top of
 * `warn`. That is right for a record's chosen colour and wrong for a colour whose entire job is to
 * be told apart at a glance, so the distance is computed here and asserted in the tests.
 */
export const intentGaps = (hue: number): Record<keyof typeof INTENT_HUE, number> =>
  Object.fromEntries(Object.entries(INTENT_HUE).map(([k, a]) => [k, hueGap(hue, a)])) as Record<
    keyof typeof INTENT_HUE,
    number
  >;
